-- =====================================================================================
-- SCRIPT DE MIGRACIÓN CONSOLIDADO: MARIADB -> POSTGRESQL (ESTÁNDAR SNAKE_CASE)
-- Usando: GENERATED BY DEFAULT AS IDENTITY
-- Incluye esquema base + migraciones (Tenant, Zonas de trabajo, Modificadores)
-- =====================================================================================

-- 0. Limpieza previa (opcional, útil para pruebas)
DROP TABLE IF EXISTS pedido_item_modificador CASCADE;
DROP TABLE IF EXISTS producto_grupo_modificador CASCADE;
DROP TABLE IF EXISTS modificador CASCADE;
DROP TABLE IF EXISTS grupo_modificador CASCADE;
DROP TABLE IF EXISTS token CASCADE;
DROP TABLE IF EXISTS pedido_item CASCADE;
DROP TABLE IF EXISTS pedido CASCADE;
DROP TABLE IF EXISTS pedido_estado CASCADE;
DROP TABLE IF EXISTS sesion CASCADE;
DROP TABLE IF EXISTS sesion_estado CASCADE;
DROP TABLE IF EXISTS producto_alergeno CASCADE;
DROP TABLE IF EXISTS producto CASCADE;
DROP TABLE IF EXISTS producto_tipo CASCADE;
DROP TABLE IF EXISTS zona_trabajo CASCADE;
DROP TABLE IF EXISTS alergeno CASCADE;
DROP TABLE IF EXISTS ingrediente CASCADE;
DROP TABLE IF EXISTS unidad CASCADE;
DROP TABLE IF EXISTS mesa CASCADE;
DROP TABLE IF EXISTS mesa_estado CASCADE;
DROP TABLE IF EXISTS zona CASCADE;
DROP TABLE IF EXISTS usuario CASCADE;
DROP TABLE IF EXISTS usuario_rol CASCADE;
DROP TABLE IF EXISTS tenant CASCADE;

-- =====================================================================================
-- 1. CREACIÓN DE TABLAS (ORDENADAS POR DEPENDENCIAS)
-- =====================================================================================

CREATE TABLE tenant (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL,
    slug VARCHAR(60) NOT NULL UNIQUE,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE alergeno (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    descripcion VARCHAR(255),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE unidad (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    simbolo VARCHAR(10) NOT NULL,
    factor INTEGER,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE ingrediente (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL UNIQUE,
    stock DECIMAL(10,2) NOT NULL DEFAULT 0.00 CHECK (stock >= 0),
    id_unidad INTEGER NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_ingrediente_unidad FOREIGN KEY (id_unidad) REFERENCES unidad (id) ON UPDATE CASCADE
);

CREATE TABLE zona_trabajo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE mesa_estado (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE zona (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    nombre VARCHAR(50) NOT NULL,
    descripcion VARCHAR(255),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_zona_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT uk_zona_tenant_nombre UNIQUE (id_tenant, nombre)
);

CREATE TABLE mesa (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    numero INTEGER NOT NULL,
    id_estado BIGINT NOT NULL,
    id_zona BIGINT,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_mesa_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT fk_mesa_estado FOREIGN KEY (id_estado) REFERENCES mesa_estado(id),
    CONSTRAINT fk_mesa_zona FOREIGN KEY (id_zona) REFERENCES zona(id),
    CONSTRAINT uk_mesa_tenant_numero UNIQUE (id_tenant, numero)
);

CREATE TABLE producto_tipo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    id_zona_trabajo BIGINT,
    nombre VARCHAR(100) NOT NULL,
    descripcion VARCHAR(200),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_producto_tipo_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT fk_producto_tipo_zona_trabajo FOREIGN KEY (id_zona_trabajo) REFERENCES zona_trabajo(id),
    CONSTRAINT uk_producto_tipo_tenant_nombre UNIQUE (id_tenant, nombre)
);

CREATE TABLE producto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    disponible BOOLEAN NOT NULL,
    precio DECIMAL(10,2) NOT NULL,
    id_tipo BIGINT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    descripcion VARCHAR(200),
    imagen VARCHAR(200),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_producto_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT fk_producto_tipo FOREIGN KEY (id_tipo) REFERENCES producto_tipo(id),
    CONSTRAINT uk_producto_tenant_nombre UNIQUE (id_tenant, nombre)
);

CREATE TABLE producto_alergeno (
    id_producto BIGINT NOT NULL,
    id_alergeno BIGINT NOT NULL,
    tipo VARCHAR(30) NOT NULL DEFAULT 'CONTIENE' CHECK (tipo IN ('CONTIENE', 'PUEDE_CONTENER_TRAZAS')),
    PRIMARY KEY (id_producto, id_alergeno),
    CONSTRAINT fk_producto_alergeno_producto FOREIGN KEY (id_producto) REFERENCES producto(id) ON DELETE CASCADE,
    CONSTRAINT fk_producto_alergeno_alergeno FOREIGN KEY (id_alergeno) REFERENCES alergeno(id) ON DELETE CASCADE
);
CREATE INDEX idx_producto_alergeno_producto ON producto_alergeno (id_producto);

CREATE TABLE usuario_rol (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    descripcion VARCHAR(200),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE usuario (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    activo BOOLEAN NOT NULL,
    rol BIGINT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    clave VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_usuario_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT fk_usuario_rol FOREIGN KEY (rol) REFERENCES usuario_rol(id),
    CONSTRAINT uk_usuario_tenant_username UNIQUE (id_tenant, nombre)
);

CREATE TABLE sesion_estado (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL UNIQUE,
    descripcion VARCHAR(200),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE sesion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    hora_fin TIMESTAMPTZ,
    hora_inicio TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    id_estado BIGINT NOT NULL,
    id_mesa BIGINT NOT NULL,
    id_usuario BIGINT,
    qr_code_url VARCHAR(50),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_sesion_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT fk_sesion_estado FOREIGN KEY (id_estado) REFERENCES sesion_estado(id),
    CONSTRAINT fk_sesion_mesa FOREIGN KEY (id_mesa) REFERENCES mesa(id),
    CONSTRAINT fk_sesion_usuario FOREIGN KEY (id_usuario) REFERENCES usuario(id)
);

CREATE TABLE pedido_estado (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    descripcion VARCHAR(200)
);

CREATE TABLE pedido (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    id_estado BIGINT NOT NULL,
    id_sesion BIGINT NOT NULL,
    total DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_pedido_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id),
    CONSTRAINT fk_pedido_estado FOREIGN KEY (id_estado) REFERENCES pedido_estado(id),
    CONSTRAINT fk_pedido_sesion FOREIGN KEY (id_sesion) REFERENCES sesion(id)
);

CREATE TABLE pedido_item (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    cantidad INTEGER NOT NULL,
    precio_unitario DECIMAL(10,2) NOT NULL,
    id_pedido BIGINT NOT NULL,
    id_producto BIGINT NOT NULL,
    id_zona_trabajo BIGINT,
    listo_para_servir BOOLEAN,
    servido BOOLEAN DEFAULT FALSE,
    nota VARCHAR(200),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_pedido_item_pedido FOREIGN KEY (id_pedido) REFERENCES pedido(id),
    CONSTRAINT fk_pedido_item_producto FOREIGN KEY (id_producto) REFERENCES producto(id),
    CONSTRAINT fk_pedido_item_zona_trabajo FOREIGN KEY (id_zona_trabajo) REFERENCES zona_trabajo(id),
    CONSTRAINT fk_pedido_item_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id)
);

CREATE TABLE refresh_token (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    token VARCHAR(256) UNIQUE NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    revoked BOOLEAN DEFAULT FALSE NOT NULL,
    usuario_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_refresh_token_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id),
    CONSTRAINT fk_refresh_token_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id)
);

CREATE TABLE grupo_modificador (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    seleccion_minima INTEGER NOT NULL DEFAULT 0,
    seleccion_maxima INTEGER NOT NULL DEFAULT 1,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_grupo_modificador_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id)

);

CREATE TABLE modificador (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    id_grupo BIGINT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    precio_extra DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_modificador_grupo FOREIGN KEY (id_grupo) REFERENCES grupo_modificador (id),
    CONSTRAINT fk_modificador_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id)
);

CREATE TABLE producto_grupo_modificador (
    id_producto BIGINT NOT NULL,
    id_grupo BIGINT NOT NULL,
    orden_visual INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY (id_producto, id_grupo),
    CONSTRAINT fk_pgm_producto FOREIGN KEY (id_producto) REFERENCES producto (id),
    CONSTRAINT fk_pgm_grupo FOREIGN KEY (id_grupo) REFERENCES grupo_modificador (id)
);

CREATE TABLE pedido_item_modificador (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tenant BIGINT NOT NULL,
    id_pedido_item BIGINT NOT NULL,
    id_modificador BIGINT NOT NULL,
    cantidad INTEGER NOT NULL DEFAULT 1,
    precio_aplicado DECIMAL(10,2) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_pim_pedido_item FOREIGN KEY (id_pedido_item) REFERENCES pedido_item (id) ON DELETE CASCADE,
    CONSTRAINT fk_pim_modificador FOREIGN KEY (id_modificador) REFERENCES modificador (id),
    CONSTRAINT fk_pim_tenant FOREIGN KEY (id_tenant) REFERENCES tenant(id)
);


