SELECT setval(pg_get_serial_sequence('pedido_estado', 'id'), COALESCE(MAX(id), 1)) FROM pedido_estado;
SELECT setval(pg_get_serial_sequence('grupo_modificador', 'id'), COALESCE(MAX(id), 1)) FROM grupo_modificador;
